export const memory: ConceptDef[] = [
  {
    t: "Views versus copies",
    lv: 2,
    s: `A slice of an array is a VIEW: a window onto the same memory. Changing the slice changes the original. {{.copy()}} makes an independent array; fancy indexing and boolean masks also return copies. {{np.shares_memory(a, b)}} tells you which you have.`,
    r: `Normalising a "slice" of your raw data in place silently corrupts the original — a classic source of leakage and irreproducible results.`,
    i: `Why did changing a slice change the original array, and how do you prevent it?`,
    c: py`
import numpy as np

a = np.array([10, 20, 30])
view = a[1:]
view[0] = 999
print(a)
b = a[1:].copy()
b[0] = 50
print(a)
print(np.shares_memory(a, view), np.shares_memory(a, b))`,
    v: trace("A slice shares memory with the original; a copy does not.", py`
import numpy as np

a = np.array([10, 20, 30])
view = a[1:]
view[0] = 999
print(a)
b = a[1:].copy()
b[0] = 50
print(a)
print(np.shares_memory(a, view), np.shares_memory(a, b))`, [
      [3, { a: "[10 20 30]" }],
      [4, { view: "a[1:]  → points INTO a" }, undefined, "No data is copied — view is a window onto positions 1 and 2 of a."],
      [5, { view: "[999 30]", a: "[ 10 999  30]" }, undefined, "Writing through the view changes a, because they share the same memory."],
      [6, undefined, "[ 10 999  30]"],
      [7, { b: "[999 30]  (independent copy)" }, undefined, ".copy() allocates new memory."],
      [8, { b: "[50 30]" }, undefined, "Changing b leaves a alone."],
      [9, undefined, "[ 10 999  30]"],
      [10, undefined, "True False", "view shares memory with a; the copy b does not."],
    ]),
  },
  {
    t: "Why vectorisation is fast",
    lv: 1,
    s: `A Python loop runs one interpreted step per element. A NumPy operation hands the whole array to compiled code that walks a contiguous block of memory. The result is the same, just much quicker on big arrays — often by one to two orders of magnitude. Always benchmark with {{%timeit}} rather than assuming.`,
    r: `Training on millions of values is only feasible because every step is a vectorised array operation.`,
    i: `Why is a NumPy expression faster than the equivalent Python loop?`,
    c: py`
import numpy as np

data = list(range(1000))
looped = [v * 2 for v in data]
arr = np.arange(1000)
vector = arr * 2
print(np.array_equal(looped, vector))
print(vector[:5])`,
    v: compare("Same answer, very different machinery.", ["Python loop", "Vectorised NumPy"], [
      ["Who does the work", "the Python interpreter, one element at a time", "compiled C code over the whole block"],
      ["Data layout", "a list of separate Python objects", "one contiguous block of raw numbers"],
      ["Code", "for v in data: …", "arr * 2"],
      ["On big numeric data", "slow", "usually far faster — measure with %timeit"],
    ], 1),
  },
  {
    t: "Common mistakes and how to avoid them",
    lv: 1,
    s: `The usual suspects: shape mismatches (print {{.shape}} first), using {{and}}/{{or}} instead of {{&}}/{{|}}, forgetting that slices are views, mixing up {{*}} and {{@}}, and letting NaNs spread. A calm habit solves most of them: inspect {{shape}}, {{dtype}} and a few values before and after every step.`,
    r: `Debugging array code is mostly checking shapes; senior engineers print them constantly.`,
    i: `An element-wise condition on an array raises "truth value is ambiguous". What went wrong?`,
    c: py`
import numpy as np

a = np.array([20, 50, 80])
try:
    a[(a > 25) and (a < 60)]
except ValueError:
    print("ValueError: use & instead of 'and'")
print(a[(a > 25) & (a < 60)])
print(np.mean([1, np.nan, 3]))`,
    v: compare("Four traps and their one-line fixes.", ["Why it happens", "Fix"], [
      ["(2,3) + (2,) → ValueError", "3 ≠ 2: shapes don't broadcast", "make it (2, 1): v[:, None]"],
      ["a > 1 and a < 5", "Python's and wants one True/False", "(a > 1) & (a < 5)"],
      ["edit a slice, original changes", "slices are views", "a[1:].copy()"],
      ["mean of data with NaN is nan", "NaN spreads through arithmetic", "np.nanmean(a)"],
    ]),
  },
  {
    t: "Integer overflow and dtype surprises",
    lv: 2,
    s: `Integer dtypes have fixed ranges and silently WRAP AROUND: a {{uint8}} (0–255) holding 200 plus 100 becomes 44, not 300. Convert first with {{astype}} when you need room. Division with {{/}} always gives floats; {{//}} floors to integers. Image pixels are {{uint8}} — a classic trap.`,
    r: `Brightening an image array in {{uint8}} produces dark speckles where values wrapped; convert to float, compute, then clip.`,
    i: `What is {{np.uint8(200) + np.uint8(100)}} supposed to give, and why?`,
    c: py`
import numpy as np

a = np.array([200, 250], dtype=np.uint8)
print(a + 100)
print(a.astype(int) + 100)
b = np.array([1, 2, 3])
print(b / 2)
print(b // 2)`,
    v: trace("uint8 can't hold 300 — it wraps around to 300 − 256 = 44.", py`
import numpy as np

a = np.array([200, 250], dtype=np.uint8)
print(a + 100)
print(a.astype(int) + 100)
b = np.array([1, 2, 3])
print(b / 2)
print(b // 2)`, [
      [3, { a: "[200 250]  (uint8: 0–255)" }],
      [4, undefined, "[ 44  94]", "200 + 100 = 300 does not fit in 0–255, so it wraps: 300 − 256 = 44 (and 350 − 256 = 94)."],
      [5, undefined, "[300 350]", "Convert to a wider type first and the sums are correct."],
      [6, { b: "[1 2 3]" }],
      [7, undefined, "[0.5 1.  1.5]", "/ always produces floats."],
      [8, undefined, "[0 1 1]", "// is floor division and keeps integers."],
    ]),
  },
  {
    t: "Comparing floats: isclose and allclose",
    lv: 2,
    s: `Decimals are stored approximately, so {{0.1 + 0.2 == 0.3}} is False. Compare with a tolerance: {{np.isclose(a, b)}} per element, {{np.allclose(a, b)}} for a whole array. Use {{np.array_equal}} only for exact integer or boolean arrays.`,
    r: `Unit tests for numeric code, and checking that two implementations of a model agree, use {{np.allclose}}.`,
    i: `Why is comparing floats with == unreliable, and what do you use instead?`,
    c: py`
import numpy as np

print(0.1 + 0.2 == 0.3)
print(np.isclose(0.1 + 0.2, 0.3))
a = np.array([0.1 + 0.2, 1.0])
b = np.array([0.3, 1.0])
print(a == b)
print(np.allclose(a, b))`,
    v: trace("Tiny rounding errors break ==; a tolerance fixes it.", py`
import numpy as np

print(0.1 + 0.2 == 0.3)
print(np.isclose(0.1 + 0.2, 0.3))
a = np.array([0.1 + 0.2, 1.0])
b = np.array([0.3, 1.0])
print(a == b)
print(np.allclose(a, b))`, [
      [3, undefined, "False", "0.1 + 0.2 is 0.30000000000000004 in binary floating point."],
      [4, undefined, "True", "isclose allows a tiny relative tolerance."],
      [5, { a: "[0.30000000000000004 1.]" }],
      [6, { b: "[0.3 1. ]" }],
      [7, undefined, "[False  True]", "Exact == fails on the first element."],
      [8, undefined, "True", "allclose: every pair is equal within tolerance."],
    ]),
  },
];

